INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein DMS nur für physische Dokumente gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Digitale Dokumente im Fokus"}, {"text": "Ja", "correct": false, "because": "Primär digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat ein DMS?', 3, '[{"text": "Dokumente verwalten", "correct": true, "because": "Speichern und Organisieren"}, {"text": "Netzwerksicherheit", "correct": false, "because": "Nicht primär"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Optionale Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features bietet ein DMS?', 5, '[{"text": "Versionskontrolle", "correct": true, "because": "Änderungen nachverfolgen"}, {"text": "Zugriffssteuerung", "correct": true, "because": "Rechte verwalten"}, {"text": "Physisches Drucken", "correct": false, "because": "Nicht Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein DMS speichert Dokumente digital. b) Es ersetzt physische Archive komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physische Archive können bleiben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem DMS?', 4, '[{"text": "Zugriffsrechte", "correct": false, "because": "Sicherheit wichtig"}, {"text": "Datenformat", "correct": false, "because": "Kompatibilität nötig"}, {"text": "Papiergröße", "correct": true, "because": "Digital irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein DMS nur für Textdokumente ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Bilder, PDFs"}, {"text": "Ja", "correct": false, "because": "Verschiedene Formate"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System ist ein Beispiel für ein DMS?', 3, '[{"text": "Alfresco", "correct": true, "because": "Bekanntes DMS"}, {"text": "MySQL", "correct": false, "because": "Datenbank"}, {"text": "Apache", "correct": false, "because": "Webserver"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein DMS?', 5, '[{"text": "Schneller Zugriff", "correct": true, "because": "Digital verfügbar"}, {"text": "Effiziente Suche", "correct": true, "because": "Metadaten"}, {"text": "Mehr Papier", "correct": false, "because": "Papier wird reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein DMS organisiert Dokumente. b) Es benötigt immer physische Scanner. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scanner optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein DMS?', 4, '[{"text": "Speicherplatz", "correct": false, "because": "Daten speichern"}, {"text": "Software", "correct": false, "because": "Grundlage"}, {"text": "Papierarchiv", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein DMS dasselbe wie eine Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "Spezialisiert auf Dokumente"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen unterstützt ein DMS?', 4, '[{"text": "Workflow-Management", "correct": true, "because": "Prozesse steuern"}, {"text": "Archivierung", "correct": true, "because": "Langzeitlagerung"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Anderes System"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein DMS nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem DMS?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Papierqualität", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein DMS speichert Metadaten. b) Es ersetzt E-Mail-Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "E-Mail separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien nutzt ein DMS?', 5, '[{"text": "Cloud-Speicher", "correct": true, "because": "Flexibler Zugriff"}, {"text": "Datenbank", "correct": true, "because": "Datenverwaltung"}, {"text": "Physische Ordner", "correct": false, "because": "Digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem DMS unwichtig?', 3, '[{"text": "Zugriffssteuerung", "correct": false, "because": "Sicherheit nötig"}, {"text": "Suchfunktion", "correct": false, "because": "Effizienz"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein DMS Workflows automatisieren?', 3, '[{"text": "Ja", "correct": true, "because": "Prozesse steuern"}, {"text": "Nein", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein DMS nur für PDFs ist?', 2, '[{"text": "Nein", "correct": true, "because": "Verschiedene Formate"}, {"text": "Ja", "correct": false, "because": "Breitere Unterstützung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für ein DMS zentral?', 4, '[{"text": "Dokumentenspeicherung", "correct": true, "because": "Kernaufgabe"}, {"text": "Physisches Scannen", "correct": false, "because": "Optional"}, {"text": "Netzwerksicherheit", "correct": false, "because": "Anderes System"}]');
